-- Squashed from 6 prior migrations (see git log) on 2026-05-04.
-- App: flashcard-app. Generated by scripts/phase4-squash-app.mjs from a
-- pg_dump --schema-only of a freshly-migrated flagship_flashcard_app DB.
--
-- This is a hand-derived baseline migration: it captures the verified-
-- green schema produced by the prior multi-file migration set, in a
-- single replayable file. `mlcl create <app>` will scaffold this as
-- migration 0010 and the runtime migration runner will apply it as a
-- single transaction at first boot.
CREATE TABLE public.cards (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    deck_id uuid NOT NULL,
    user_id uuid NOT NULL,
    front text NOT NULL,
    back text NOT NULL,
    state text DEFAULT 'new'::text NOT NULL,
    ease_factor numeric(4,2) DEFAULT 2.5 NOT NULL,
    interval_days integer DEFAULT 0 NOT NULL,
    repetitions integer DEFAULT 0 NOT NULL,
    next_review timestamp with time zone DEFAULT now() NOT NULL,
    last_reviewed timestamp with time zone,
    total_reviews integer DEFAULT 0 NOT NULL,
    lapses integer DEFAULT 0 NOT NULL,
    tags jsonb DEFAULT '[]'::jsonb NOT NULL,
    image_url text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);


